import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { HttpError } from '../../api/http';
import { useSubmitOnce } from '../../forms/useSubmitOnce';
import { BulkOpen } from '../claims/BulkOpen';
import { PasteClaims } from '../claims/PasteClaims';
import { BulkSettle } from '../claims/BulkSettle';
import { PersonClaims } from '../claims/PersonClaims';
import { backing, claimsKey, isActive, listClaims, liveClaims, sumAmounts } from '../claims/api';
import { listPeriods, periodsKey, personPeriodDue } from '../periods/api';
import { claimDue, excessOf, listRates, overdue, personDue, rateByGrade, ratesKey, showDue } from '../rates/api';
import { useCap, useFloor, useLate } from '../settings/api';
import { useSheetToday } from '../sheet/api';
import { BulkGrade } from './BulkGrade';
import { ExportPeople } from './ExportPeople';
import { QuickAdd } from './QuickAdd';
import { ShowRetired, useShowRetired } from './ShowRetired';
import { GRADES, addPatron, addPerson, cancelStatement, gradeOn, holdPerson, listPeople, listWatches, peopleKey, retirePerson, takeStatement, updatePerson, watchPerson, watchesKey, type Person, type PersonInput } from './api';

const EMPTY: PersonInput = { name: '', grade: 'A', gradeFrom: '', terms: '' };

/** The people on the sheet: a form that adds a person or edits one, and the list in added order,
 *  each with their grade in force on the sheet's today, their claimed total, their due-total (the sum of their claims' due figures, at most the sheet's cap, with the excess above it; n/a
 *  when their grade has no rate on the sheet's today and no settled or stated claim keeps a figure),
 *  their statements (a button that takes one, now or as of the date typed beside it, a button that cancels the last, the count, the last one's due-total and date), whether
 *  they are retired and from when (with a date and a button that retires them), whether they have
 *  any hold, their holds (each from a date to an optional date, with dates and a button that adds one;
 *  their OPEN claims dated within a hold, and not bound by a statement, count in no total), their
 *  patrons (names sorted, with a picker that names one more) and backing (see `backing`), and
 *  their due-total for each period (see `personPeriodDue`), their overdue claims (OPEN ones past their due-by; the count and their due added up) and their claims, each
 *  with a checkbox that selects it for a button that opens the selected claims together.
 *  Each person has a checkbox that selects them for a grade given to the selected people together.
 *  Retired people are left out of the list unless "show retired" is on; their claims still count.
 *  Whether each person is active (see `isActive`).
 *  Whether the signed-in user watches each person, with a button that starts or stops it.
 *  A button exports everyone, retired people included, as a CSV file. */
export function People({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  const rates = useQuery({ queryKey: ratesKey(sheetId), queryFn: () => listRates(sheetId) });
  const watches = useQuery({ queryKey: watchesKey(sheetId, user), queryFn: () => listWatches(sheetId, user) });
  const watched = new Set(watches.data ?? []);
  const periods = useQuery({ queryKey: periodsKey(sheetId), queryFn: () => listPeriods(sheetId) });
  const floor = useFloor(sheetId);
  const today = useSheetToday(sheetId, user);
  const cap = useCap(sheetId, today);
  const charges = useLate(sheetId, today);
  const byGrade = rateByGrade(rates.data, today);
  const [form, setForm] = useState<PersonInput>(EMPTY);
  // The person being edited and the version of them the form loaded.
  const [editing, setEditing] = useState<{ id: number; version: number } | null>(null);
  const [showRetired] = useShowRetired();
  // The retirement date typed on each person's row (blank: the sheet's today).
  const [retireDates, setRetireDates] = useState<Record<number, string>>({});
  // The statement date typed on each person's row (blank: the statement is taken now).
  const [asOfDates, setAsOfDates] = useState<Record<number, string>>({});
  // The hold dates typed on each person's row (blank from: the sheet's today; blank to: open-ended).
  const [holdDates, setHoldDates] = useState<Record<number, { from: string; to: string }>>({});
  // The patron picked on each person's row (blank: none picked).

  const hold = (id: number) => {
    const { from = '', to = '' } = holdDates[id] ?? {};
    stateOnce(() => {
      resetRowActions();
      return holding.mutateAsync({ id, from, to });
    });
  };

  const changeHold = (id: number, patch: Partial<{ from: string; to: string }>) => {
    setHoldDates((d) => ({ ...d, [id]: { from: '', to: '', ...d[id], ...patch } }));
    holding.reset();
  };

  const patronize = (id: number) => {
    const patronId = Number(patronPicks[id] ?? '');
    stateOnce(() => {
      resetRowActions();
      return patronage.mutateAsync({ id, patronId });
    });
  };

  const change = (patch: Partial<PersonInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    save.reset();
  };

  const open = (p: Person) => {
    setForm({ name: p.name, grade: p.grade, gradeFrom: '', terms: p.terms === null ? '' : String(p.terms) });
    setEditing({ id: p.id, version: p.version });
    save.reset();
  };

  const cancel = () => {
    setForm(EMPTY);
    setEditing(null);
    save.reset();
  };

  // Everyone's due-total as their row shows it (null: n/a), and their names, by id.
  const everyone = people.data ?? [];
  const dueOf = new Map(everyone.map((q) => [q.id, personDue(
    liveClaims((claims.data ?? []).filter((c) => c.personId === q.id), [q]),
    rates.data, (d) => gradeOn(q, d), byGrade.get(q.grade), floor, charges, cap)]));
  const nameOf = new Map(everyone.map((q) => [q.id, q.name]));

  return (
    <section>
      <h3>People</h3>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          const v = { editing, input: form };
          submitOnce(() => {
            save.reset();
            return save.mutateAsync(v);
          });
        }}
      >
        <label>
          Name{' '}
          <input data-testid="person-form-name" value={form.name} onChange={(e) => change({ name: e.target.value })} />
        </label>{' '}
        <label>
          Grade{' '}
          <select data-testid="person-form-grade" value={form.grade} onChange={(e) => change({ grade: e.target.value })}>
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          from{' '}
          <input type="date" data-testid="person-form-grade-from" value={form.gradeFrom}
            onChange={(e) => change({ gradeFrom: e.target.value })} />
        </label>{' '}
        <label>
          Terms{' '}
          <input data-testid="person-form-terms" value={form.terms} placeholder="days"
            onChange={(e) => change({ terms: e.target.value })} />
        </label>{' '}
        <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
          {editing === null ? 'Add person' : 'Save person'}
        </button>
        {editing !== null && (
          <button type="button" data-testid="person-form-cancel" onClick={cancel}>
            Cancel
          </button>
        )}
        {save.isError && (
          <span data-testid="person-form-error">
            {save.error instanceof HttpError && save.error.status === 409
              ? 'Someone else saved this person meanwhile: the form shows what is stored now. Open the editor again to edit it.'
              : 'A person needs a name not already in use, and terms (if any) a whole number of days.'}
          </span>
        )}
      </form>
      <QuickAdd sheetId={sheetId} user={user} />
      <PasteClaims sheetId={sheetId} user={user} />
      <ShowRetired />{' '}
      <ExportPeople rows={() => everyone.map((p) => [p.name, gradeOn(p, today), p.retiredFrom ?? '', showDue(dueOf.get(p.id) ?? null)])} />
      <BulkOpen sheetId={sheetId} user={user} selected={[...selected]} onDone={() => setSelected(new Set())} />
      <BulkGrade sheetId={sheetId} user={user} selected={[...selectedPeople]} onDone={() => setSelectedPeople(new Set())} />
      <BulkSettle sheetId={sheetId} user={user} selected={[...selected]} onDone={() => setSelected(new Set())} />
      {people.isError && <p data-testid="people-error">The people could not be loaded.</p>}
      <table>
        <tbody>
          {(people.data ?? []).filter((p) => showRetired || !p.retired).map((p) => {
            const own = (claims.data ?? []).filter((c) => c.personId === p.id);
            const live = liveClaims(own, [p]);
            const claimed = sumAmounts(live);
            const pct = byGrade.get(p.grade);
            const late = overdue(live, today, (c) => claimDue(c, rates.data, (d) => gradeOn(p, d), floor, charges));
            return (
              <tr key={p.id} data-testid={`person-row-${p.id}`}>
                <td>
                  <input type="checkbox" data-testid="person-select" checked={selectedPeople.has(p.id)}
                    onChange={(e) => selectPerson(p.id, e.target.checked)} />
                </td>
                <td data-testid="person-name">{p.name}</td>
                <td data-testid="person-grade">{p.grade}</td>
                <td>
                  Active <span data-testid="person-active">{isActive(live, today) ? 'yes' : 'no'}</span>
                </td>
                <td>
                  Terms <span data-testid="person-terms">{p.terms ?? ''}</span>
                </td>
                <td>
                  Claimed <span data-testid="person-claimed">{claimed}</span>
                </td>
                <td>
                  Due <span data-testid="person-due-total">{showDue(personDue(live, rates.data, (d) => gradeOn(p, d), pct, floor, charges, cap))}</span>{' '}
                  excess <span data-testid="person-excess">{excessOf(live, rates.data, (d) => gradeOn(p, d), pct, floor, charges, cap)}</span>
                </td>
                {(periods.data ?? []).map((q) => (
                  <td key={q.name}>
                    {q.name} <span data-testid={`person-period-${q.name}-due-total`}>
                      {personPeriodDue(q, p, claims.data ?? [], people.data, rates.data, floor, charges)}</span>
                  </td>
                ))}
                <td>
                  Overdue <span data-testid="person-overdue-count">{late.count}</span>{' '}
                  totalling <span data-testid="person-overdue-total">{late.total}</span>
                </td>
                <td>
                  <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => open(p)}>
                    Edit
                  </button>
                </td>
                <td>
                  <input type="date" data-testid="person-statement-asof" value={asOfDates[p.id] ?? ''}
                    onChange={(e) => {
                      setAsOfDates((d) => ({ ...d, [p.id]: e.target.value }));
                      statement.reset();
                    }} />{' '}
                  <button type="button" data-testid="person-statement" disabled={statement.isPending}
                    onClick={() => state(p.id)}>
                    Statement
                  </button>{' '}
/** A claim's rate figure: an amount times a percent, divided by 100, rounded to two decimals (half up
 *  when `halfUp`, else half to even; no floor: that is applied last, by `claimDue`);
 *  null (n/a) when there is no rate. Exact: worked in whole hundredths. */
export function dueOf(amount: string, pct: string | undefined, halfUp: boolean): string | null {
  if (pct === undefined) return null;
  // amount (1/100) x pct (1/100) / 100 is in 1/1_000_000; to cents is / 10_000.
  return formatCents(roundPct(hundredths(amount) * hundredths(pct), halfUp));
}

/** What a claim's late charge goes by: the sheet's late percent by date (a charge goes by the one in force on each 30-day boundary) and its today (a claim's due-by is its own);
 *  and the sheet's policy date (its today when blank), which decides how a claim's live figures round. */
export type Late = { pct: DatedOn; today: string; policy: string };

/** Whether a claim's live figures round half up: its round date (its own, or for a correction the
 *  date of the claim it corrects) is before the policy date; else they round half to even. */
export const roundsHalfUp = (c: Claim, late: Late) => (c.roundDate ?? c.date) < late.policy;

/** The late charge on an open (OPEN or PENDING) claim's `figure`: for each full 30 days it is past its due-by on
 *  the sheet's today, the late percent in force on that boundary date (its due-by plus 30, 60, 90 ... days) of it,
 *  each rounded by the policy date to two decimals, added up (0 when not overdue, and on a correction). */
export function lateCharge(c: Claim, figure: string, late: Late): bigint {
  if (isCorrection(c) || !isOverdue(c, late.today)) return 0n;
  const start = Date.parse(`${dueBy(c)}T00:00:00Z`);
  const periods = Math.floor((Date.parse(`${late.today}T00:00:00Z`) - start) / 86_400_000 / 30);
  let total = 0n;
  for (let k = 1; k <= periods; k++) {
    const boundary = new Date(start + k * 30 * 86_400_000).toISOString().slice(0, 10);
    total += roundPct(hundredths(figure) * hundredths(late.pct(boundary)), roundsHalfUp(c, late));
  }
  return total;
}

/** A person's grade in force on a date (yyyy-MM-dd). */
export type GradeOn = (date: string) => string;

/** A claim's due: the one fixed when it was settled (its late charge then frozen in), else its
 *  figure — the one bound by its person's last statement (not while PENDING; n/a when it bound none), else live at the rate in force on the
 *  claim's date of the grade in force then (`gradeOn`) — with its late charge on the sheet's today on top, and
 *  at least the `floor` in force on its date, applied last (a correction, a negative amount, has no floor). */
export function claimDue(c: Claim, rates: Rate[] | undefined, gradeOn: GradeOn, floor: DatedOn, late: Late): string | null {
  if (c.settledDue !== null) return c.settledDue;
  const figure = c.stated && c.status !== 'PENDING' ? c.statedDue : dueOf(c.amount, rateOn(rates, gradeOn(c.date), c.date), roundsHalfUp(c, late));
  if (figure === null) return null;
  const due = hundredths(figure) + lateCharge(c, figure, late);
  const least = hundredths(floor(c.date));
  return formatCents(!isCorrection(c) && due < least ? least : due);
}

/** A product of hundredths and a percent's hundredths (in 1/1_000_000) to cents, half up (away
 *  from zero) when `halfUp`, else half to even (symmetric about zero). */
function roundPct(product: bigint, halfUp: boolean): bigint {
  if (product < 0n) return -roundPct(-product, halfUp);
  const whole = product / 10_000n;
  const rest = product % 10_000n;
  return rest > 5_000n || (rest === 5_000n && (halfUp || whole % 2n === 1n)) ? whole + 1n : whole;
}

/** A person's due-total: the sum of their counting claims' due figures (n/a ones skipped), at
 *  most the sheet's `cap` (null: no cap); n/a
 *  when their grade today has no rate today (`pct`) and none of those claims keeps a settled or bound
 *  figure, or a live one at a grade no longer in force on the sheet's today or dated on or before it
 *  (its rate since ended). */
export function personDue(claims: Claim[], rates: Rate[] | undefined, gradeOn: GradeOn, pct: string | undefined,
  floor: DatedOn, late: Late, cap: string | null) {
  const own = claims.filter(counts);
  const now = gradeOn(late.today);
  const kept = (c: Claim) => c.settledDue !== null || isBound(c)
    || ((gradeOn(c.date) !== now || c.date <= late.today) && rateOn(rates, gradeOn(c.date), c.date) !== undefined);
  if (pct === undefined && !own.some(kept)) return null;
  const sum = sumDues(own.map((c) => claimDue(c, rates, gradeOn, floor, late)));
  return cap !== null && hundredths(sum) > hundredths(cap) ? formatCents(hundredths(cap)) : sum;
}

/** What a person's due figures add up to above the sheet's `cap` (null: no cap); 0.00 when they do
 *  not exceed it, or their due-total is n/a. */
export function excessOf(claims: Claim[], rates: Rate[] | undefined, gradeOn: GradeOn, pct: string | undefined,
  floor: DatedOn, late: Late, cap: string | null): string {
  const full = personDue(claims, rates, gradeOn, pct, floor, late, null);
  return full === null || cap === null || hundredths(full) <= hundredths(cap) ? '0.00'
    : formatCents(hundredths(full) - hundredths(cap));
}

/** The overdue claims among those that count (`claims`, the live ones): their count and the sum
 *  of their due figures (n/a ones skipped). */
export function overdue(claims: Claim[], today: string, dueOfClaim: (c: Claim) => string | null) {
  const late = claims.filter((c) => isOverdue(c, today));
  return { count: late.length, total: sumDues(late.map(dueOfClaim)) };
}

/** Add up two-decimal dues, skipping n/a. */
export function sumDues(dues: Array<string | null>): string {
  return formatCents(dues.reduce<bigint>((t, d) => (d === null ? t : t + hundredths(d)), 0n));
}

/** A sheet total of per-person figures: added up (n/a ones are no figure), leaving out the single
 *  highest and the single lowest figure when there are three or more. */
export function trimmedSum(figures: Array<string | null>): string {
  const cents = figures.filter((f): f is string => f !== null).map(hundredths).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const kept = cents.length >= 3 ? cents.slice(1, -1) : cents;
  return formatCents(kept.reduce((t, c) => t + c, 0n));
}

function formatCents(cents: bigint): string {
  const abs = cents < 0n ? -cents : cents;
  const frac = (abs % 100n).toString().padStart(2, '0');
  return `${cents < 0n ? '-' : ''}${abs / 100n}.${frac}`;
}

/** A due as shown: n/a when there is none. */
export const showDue = (due: string | null) => due ?? 'n/a';

